    let body='';
    if(state.taskView==='list') body=`<div class="card"><ul class="list">${state.tasks.map(taskRow).join('')}</ul></div>`;
    if(state.taskView==='kanban') body=`<div class="kanban">${[['收集箱','inbox'],['已计划','planned'],['进行中','in-progress']].map(c=>`<div class="kanban-col"><div class="section-head"><h3>${c[0]}</h3>${stage(open.filter(t=>t.status===c[1]).length)}</div>${open.filter(t=>t.status===c[1]).map(t=>`<div class="task-card"><div class="card-title">${esc(t.title)}</div><div class="card-meta">${esc(t.scheduled)}</div>${btn('完成','toggle-task','text small',`data-id="${t.id}"`)}</div>`).join('')||'<div class="empty">此列为空</div>'}</div>`).join('')}</div>`;
    if(state.taskView==='matrix') body=`<div class="layout-grid cols-even">${[[true,true,'重要且紧急'],[true,false,'重要不紧急'],[false,true,'不重要但紧急'],[false,false,'不重要不紧急']].map(q=>`<div class="card tonal"><h3>${q[2]}</h3>${open.filter(t=>t.important===q[0]&&t.urgent===q[1]).map(t=>`<div class="task-card"><div class="card-title">${esc(t.title)}</div><div class="card-meta">${esc(t.deadline)}</div></div>`).join('')||'<p class="muted">没有任务</p>'}</div>`).join('')}</div>`;
    $('#view').innerHTML=`<div class="toolbar"><div class="segmented"><button class="${state.taskView==='list'?'active':''}" data-action="task-view" data-value="list">列表</button><button class="${state.taskView==='kanban'?'active':''}" data-action="task-view" data-value="kanban">看板</button><button class="${state.taskView==='matrix'?'active':''}" data-action="task-view" data-value="matrix">四象限</button></div><span class="spacer"></span>${stage('同一任务数据')}</div>${body}`;
