  function financeSummary() {
    const cny=state.accounts.filter(a=>a.currency==='CNY').reduce((s,a)=>s+a.balance,0);
    const income=state.transactions.filter(t=>t.type==='INCOME'&&t.currency==='CNY').reduce((s,t)=>s+t.amount,0);
    const expense=state.transactions.filter(t=>t.type==='EXPENSE'&&t.currency==='CNY').reduce((s,t)=>s+t.amount,0);
    return {cny,income,expense};
  }
