  function generateSecret() {
    const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%'; const bytes=new Uint32Array(20); crypto.getRandomValues(bytes); return Array.from(bytes,n=>chars[n%chars.length]).join('');
  }
  function viewPasswordGenerator() {
    page('生成器与条目','使用 crypto.getRandomValues 生成仅供演示的随机字符串；不作为生产安全承诺。',btn('生成','password-generate','filled'));
    if(!secure.generated) secure.generated=generateSecret();
    $('#view').innerHTML=`<section class="layout-grid cols-2"><div class="card"><div class="field"><label>演示生成结果</label><div class="input mono" style="display:flex;align-items:center;justify-content:space-between"><span>${esc(secure.generated)}</span><button class="icon-button" data-action="copy-generated" aria-label="复制生成结果">${icon('download')}</button></div></div><div class="field" style="margin-top:18px"><label>长度 · 20</label><input type="range" min="12" max="64" value="20" aria-label="密码长度"></div><div class="layout-grid cols-even"><label><input type="checkbox" checked> 大写字母</label><label><input type="checkbox" checked> 小写字母</label><label><input type="checkbox" checked> 数字</label><label><input type="checkbox" checked> 符号</label></div></div><aside class="card tonal"><h2>条目类型与阶段</h2><p>Login ${stage('P0')} · 安全短笔记 ${stage('P0')} · Card ${stage('P0')} · Identity ${stage('P0')}</p><p>TOTP ${stage('P0')} · API Credential ${stage('P1')} · SSH ${stage('P1')} · Passkey ${stage('P1')}</p></aside></section>`;
  }

